package net.battlespades.bot;
import java.util.*;
import static net.battlespades.bot.BotFoundationsTest.*;
import static net.battlespades.bot.BotPlayerTestData.player;
import static net.battlespades.bot.BotPerceptionTestData.*;
import static net.battlespades.bot.BotSourceFixture.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BotModePoliciesTest {
 static final Map<String,Object> SOURCE=read("bot-modes");
 @Test void strategiesRolesAndCommitmentMatchEverySourceBoundary(){for(var o:list(SOURCE.get("strategies"))){var r=map(o);matches(r.get("canonical"),BotModePolicies.canonical(string(r.get("input"))));matches(r.get("strategy"),BotModePolicies.strategy(string(r.get("input"))));}for(var o:list(SOURCE.get("traces"))){var trace=map(o);var policies=new BotModePolicies();var memory=new BotModePolicies.Memory(policies);int index=0;for(var v:list(trace.get("rows"))){var r=map(v);var frame=frame(r.get("frame"));var p=player(r.get("observer"));try{matches(r.get("raw"),policies.objectiveDecision(frame,p));matches(r.get("standing"),BotModePolicies.standingOrder(frame,p));var d=memory.decide(frame,p);matches(r.get("decision"),d);matches(r.get("committed"),BotModePolicies.committed(d));var targets=list(r.get("targets"));for(int i=0;i<targets.size();i++)matches(list(r.get("combat")).get(i),BotModePolicies.allowsCombat(d,p,player(targets.get(i)),frame.createdAt()));matches(r.get("memory"),memory.snapshot());}catch(AssertionError e){throw new AssertionError(trace.get("code")+" boundary "+index,e);}index++;}}}
 @Test void communityDecisionsUsePublishedFunFacts(){for(var o:list(SOURCE.get("fun"))){var r=map(o);var f=frame(r.get("frame"));try{matches(r.get("decision"),new BotModePolicies().objectiveDecision(f,player(r.get("observer"))));}catch(AssertionError e){throw new AssertionError(f.mode()+" community frame "+f.frameId(),e);}}}
 static TeamTasks.Identity identity(Object o){var a=list(o);return new TeamTasks.Identity(integer(a.get(0)),integer(a.get(1)),integer(a.get(2)));}
 @Test void teamLeasesAndMutationBucketsRetainSourceBudgets(){var tasks=new TeamTasks();for(var o:list(SOURCE.get("tasks"))){var r=map(o);var p=map(r.get("project"));var project=new TeamTasks.Project(number(p.get("project_id")),integer(p.get("team")),string(p.get("kind")),identity(p.get("owner")),vector(p.get("position")),vector(p.get("lane")),real(p.get("created_at")),real(p.get("expires_at")),list(p.get("cells")).stream().map(BotFoundationsTest::cell).toList(),real(p.get("last_progress_at")));project.participants.put(new TeamTasks.Identity(100,1,1),3+project.createdAt);matches(r.get("accepted"),tasks.reserve(project));var observed=new LinkedHashMap<TeamTasks.Observer,TeamTasks.Observed>();for(var v:list(r.get("observed"))){var a=list(v);observed.put(new TeamTasks.Observer(integer(a.get(0)),integer(a.get(1))),new TeamTasks.Observed(bool(a.get(2)),integer(a.get(3))));}double now=real(r.get("now"));tasks.expire(now,observed);int id=(int)project.id;boolean allowed=tasks.allowMutation(id%2,now,1+id%5);matches(r.get("allowed"),allowed);if(allowed)tasks.recordMutation(id%2,now,1+id%5);tasks.event(bool(r.get("accepted"))?"accepted":"rejected",id,"fixture",now);matches(r.get("projects"),tasks.projects().keySet());var history=new LinkedHashMap<String,Object>();for(var k:map(r.get("history")).keySet())history.put(k,tasks.mutations(Integer.parseInt(k)).stream().map(m->List.of(m.at(),m.cells())).toList());matches(r.get("history"),history);matches(r.get("metrics"),tasks.metrics());matches(r.get("events"),tasks.events());}}
 @Test void sensoryEvidenceExpiresWithoutHiddenRosterRefresh(){var memory=new BehaviorMemory();for(var o:list(SOURCE.get("behavior"))){var r=map(o);var f=frame(r.get("frame"));var p=player(r.get("observer"));memory.observe(f,p,r.get("visible")==null?null:player(r.get("visible")));var record=map(r.get("record"));memory.record(string(record.get("kind")),vector(record.get("position")),real(record.get("now")),bool(record.get("success")));matches(r.get("contact"),memory.contact(p.position(),f.createdAt()));matches(r.get("penalty"),memory.penalty("cover",new net.battlespades.physics.PlayerPhysics.Vector(60,80,97.75),f.createdAt()));var state=memory.snapshot();var contacts=new ArrayList<Object>();state.contacts().forEach((k,v)->contacts.add(Map.of("key",List.of(k.x(),k.y(),k.kind()),"value",v)));matches(r.get("contacts"),contacts);matches(r.get("outcomes"),state.outcomes().stream().map(v->List.of(v.kind(),v.position(),v.at(),v.success())).toList());matches(r.get("pressure"),state.pressure());matches(r.get("updated_at"),state.updatedAt());}}
 @Test void mutableModeAndTaskMemoryRejectsOtherThreads()throws Exception{var policies=new BotModePolicies();var memory=new BotModePolicies.Memory(policies);var tasks=new TeamTasks();var failures=new java.util.concurrent.atomic.AtomicInteger();var thread=new Thread(()->{for(Runnable r:List.<Runnable>of(policies::reset,memory::reset,tasks::metrics))try{r.run();}catch(IllegalStateException expected){failures.incrementAndGet();}});thread.start();thread.join();assertEquals(3,failures.get());}
}
